create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists public.reports(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type text not null check(type in ('url','message','claim','image','document','video','audio')),subject text not null,score integer check(score between 0 and 100),confidence integer check(confidence between 0 and 100),risk text,headline text,summary text,recommendation text,limitations jsonb not null default '[]'::jsonb,signals jsonb not null default '[]'::jsonb,scoring_version text not null default 'v1',engine_version text not null default 'mvp-1',created_at timestamptz not null default now());
create index if not exists reports_user_created_idx on public.reports(user_id,created_at desc);
alter table public.profiles enable row level security;alter table public.reports enable row level security;
create policy "profiles own row" on public.profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "reports own rows" on public.reports for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id) values(new.id) on conflict do nothing; return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();